    private Dispatch() { }
    public Dispatch(string number,string packingSlip,WorkOrder wo,decimal quantity,DateOnly? date,string shippingAddress,string? contact,string? phone,string? remarks)
    {
        DispatchNumber=Required(number);PackingSlipNumber=Required(packingSlip);WorkOrderId=wo.Id;WorkOrderNumber=wo.WorkOrderNumber;
        SalesOrderId=wo.SalesOrderId;SalesOrderNumber=wo.SalesOrderNumber;SalesOrderLineId=wo.SalesOrderLineId;CustomerId=wo.CustomerId;
        CustomerCode=wo.CustomerCode;CustomerName=wo.CustomerName??"Inventory Customer";CustomerPONumber=wo.CustomerPONumber;
        ProductType=wo.ProductType;Description=wo.Description;GradeCode=wo.GradeCode??wo.Grade?.Code;Thickness=wo.Thickness;Width=wo.RequiredWidth;
        DrawingNumber=wo.DrawingNumber;DrawingRevision=wo.DrawingRevision;OEMJobNumber=wo.OEMJobNumber;TransformerRating=wo.TransformerRating;
        Category=wo.Category;CoreLossPerKg=wo.CoreLossPerKg;DispatchQuantity=quantity;QuantityUnit=wo.QuantityUnit;DispatchDate=date;
        ShippingAddress=Required(shippingAddress);ContactPerson=Optional(contact);ContactPhone=Optional(phone);DispatchRemarks=Optional(remarks);Status=DispatchStatus.Draft;
    }
    public string DispatchNumber{get;private set;}="";public string PackingSlipNumber{get;private set;}="";public Guid WorkOrderId{get;private set;}public WorkOrder? WorkOrder{get;private set;}public string WorkOrderNumber{get;private set;}="";
    public Guid? SalesOrderId{get;private set;}public string? SalesOrderNumber{get;private set;}public Guid? SalesOrderLineId{get;private set;}public Guid? CustomerId{get;private set;}public string? CustomerCode{get;private set;}public string CustomerName{get;private set;}="";public string? CustomerPONumber{get;private set;}
    public WorkOrderProductType ProductType{get;private set;}public string Description{get;private set;}="";public string? GradeCode{get;private set;}public decimal? Thickness{get;private set;}public decimal? Width{get;private set;}public string? DrawingNumber{get;private set;}public string? DrawingRevision{get;private set;}public string? OEMJobNumber{get;private set;}public string? TransformerRating{get;private set;}public string? Category{get;private set;}public decimal? CoreLossPerKg{get;private set;}
    public decimal DispatchQuantity{get;private set;}public QuantityUnit QuantityUnit{get;private set;}public decimal? NetWeight{get;private set;}public decimal? GrossWeight{get;private set;}public int? NumberOfPackages{get;private set;}public DateOnly? DispatchDate{get;private set;}
    public string? TransporterName{get;private set;}public string? VehicleNumber{get;private set;}public string? LRGRNumber{get;private set;}public DateOnly? LRGRDate{get;private set;}public string? EWayBillNumber{get;private set;}public DateOnly? EWayBillDate{get;private set;}public string ShippingAddress{get;private set;}="";public string? ContactPerson{get;private set;}public string? ContactPhone{get;private set;}public string? PackingRemarks{get;private set;}public string? DispatchRemarks{get;private set;}
    public DispatchStatus Status{get;private set;}public string? DispatchedBy{get;private set;}public DateTimeOffset? DispatchedOn{get;private set;}public string? CancelledBy{get;private set;}public DateTimeOffset? CancelledOn{get;private set;}public string? CancellationReason{get;private set;}public byte[] RowVersion{get;private set;}=[];
    public IReadOnlyCollection<DispatchPackage> Packages=>_packages;public IReadOnlyCollection<DispatchInventorySource> InventorySources=>_inventorySources;
