    {if(Status!=DispatchStatus.Draft)throw new InvalidOperationException("Only Draft Dispatches can be edited.");DispatchQuantity=quantity;DispatchDate=date;ShippingAddress=Required(shippingAddress);ContactPerson=Optional(contact);ContactPhone=Optional(phone);NetWeight=net;GrossWeight=gross;TransporterName=Optional(transporter);VehicleNumber=Optional(vehicle);LRGRNumber=Optional(lrgr);LRGRDate=lrgrDate;EWayBillNumber=Optional(eway);EWayBillDate=ewayDate;PackingRemarks=Optional(packingRemarks);DispatchRemarks=Optional(dispatchRemarks);_packages.Clear();_packages.AddRange(packages);NumberOfPackages=_packages.Count;}
